export interface ConnectorConfig {
  /** Google OAuth access token (may be expired). */
  googleOAuthAccessToken: string
  /** Google OAuth refresh token used to obtain a new access token. */
  googleOAuthRefreshToken: string
  /** Google OAuth client ID. */
  googleOAuthClientId: string
  /** Google OAuth client secret. */
  googleOAuthClientSecret: string
  /** Google Sheets spreadsheet ID. */
  spreadsheetId: string
  /** A1 notation range where the table exists, e.g. "Sheet1!A:B". */
  range: string
  /** Value input option: "RAW" or "USER_ENTERED". Defaults to "USER_ENTERED". */
  valueInputOption?: 'RAW' | 'USER_ENTERED'
  /** Insert data option: "OVERWRITE" or "INSERT_ROWS". Defaults to "OVERWRITE". */
  insertDataOption?: 'OVERWRITE' | 'INSERT_ROWS'
  /** Whether to include updated values in response. Defaults to true. */
  includeValuesInResponse?: boolean
  /** Injected fetch for testing. */
  fetch?: typeof fetch
}

export interface HubSpotDealUpdatedPayload {
  subscriptionId: string
  portalId: string
  eventId: string
  subscriptionType: string
  timestamp: number
  attemptNumber: number
  objectId: string
  propertyName: string
  propertyValue: string
  propertySource: string
  hs_object_id: string
  dealstage: string
  dealstageid?: string
}

export interface HandleResult {
  spreadsheetId: string
  updatedRange: string
  updatedRows: number
  updatedColumns: number
  updatedCells: number
}

async function refreshAccessToken(config: ConnectorConfig): Promise<string> {
  const fetchImpl = config.fetch ?? fetch
  const tokenUrl = 'https://oauth2.googleapis.com/token'
  const body = new URLSearchParams({
    client_id: config.googleOAuthClientId,
    client_secret: config.googleOAuthClientSecret,
    refresh_token: config.googleOAuthRefreshToken,
    grant_type: 'refresh_token',
  })

  const response = await fetchImpl(tokenUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: body.toString(),
  })

  if (!response.ok) {
    const errorText = await response.text()
    throw new Error(`Failed to refresh Google OAuth token: ${response.status} ${response.statusText} - ${errorText}`)
  }

  const data = await response.json() as { access_token: string; expires_in: number }
  return data.access_token
}

async function appendToSheets(
  config: ConnectorConfig,
  accessToken: string,
  values: string[],
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch
  const encodedRange = encodeURIComponent(config.range)
  const url = `https://sheets.googleapis.com/v4/spreadsheets/${config.spreadsheetId}/values/${encodedRange}:append`

  const params = new URLSearchParams()
  params.set('valueInputOption', config.valueInputOption ?? 'USER_ENTERED')
  if (config.insertDataOption) params.set('insertDataOption', config.insertDataOption)
  if (config.includeValuesInResponse !== false) params.set('includeValuesInResponse', 'true')

  const fullUrl = `${url}?${params.toString()}`

  const requestBody = {
    majorDimension: 'ROWS',
    range: config.range,
    values: [values],
  }

  const response = await fetchImpl(fullUrl, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(requestBody),
  })

  if (response.status === 401) {
    throw new Error('UNAUTHORIZED')
  }

  if (!response.ok) {
    const errorText = await response.text()
    throw new Error(`Google Sheets append failed: ${response.status} ${response.statusText} - ${errorText}`)
  }

  const data = await response.json() as {
    spreadsheetId: string
    tableRange: string
    updates: {
      spreadsheetId: string
      updatedRange: string
      updatedRows: number
      updatedColumns: number
      updatedCells: number
    }
  }

  return {
    spreadsheetId: data.spreadsheetId,
    updatedRange: data.updates.updatedRange,
    updatedRows: data.updates.updatedRows,
    updatedColumns: data.updates.updatedColumns,
    updatedCells: data.updates.updatedCells,
  }
}

export async function handle(
  payload: HubSpotDealUpdatedPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  // Validate required fields
  if (!payload.dealstage) {
    throw new Error('Missing required field: dealstage')
  }
  if (!payload.hs_object_id && !payload.objectId) {
    throw new Error('Missing required field: deal ID (hs_object_id or objectId)')
  }

  const dealStage = payload.dealstage
  const dealStageId = payload.dealstageid ?? ''

  let accessToken = config.googleOAuthAccessToken

  try {
    return await appendToSheets(config, accessToken, [dealStage, dealStageId])
  } catch (error) {
    if (error instanceof Error && error.message === 'UNAUTHORIZED') {
      // Refresh token and retry once
      accessToken = await refreshAccessToken(config)
      return await appendToSheets(config, accessToken, [dealStage, dealStageId])
    }
    throw error
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, HubSpotDealUpdatedPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      googleOAuthAccessToken: 'ya29.initial-token',
      googleOAuthRefreshToken: 'refresh-token-123',
      googleOAuthClientId: 'client-id',
      googleOAuthClientSecret: 'client-secret',
      spreadsheetId: '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
      range: 'Sheet1!A:B',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealUpdatedPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.spreadsheetId).toBe('1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms')
    expect(result.updatedRange).toBe('Sheet1!A2:B2')
    expect(result.updatedRows).toBe(1)
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let fetchMock: ReturnType<typeof fakeFetch>['fetch']
  let calls: ReturnType<typeof fakeFetch>['calls']

  beforeEach(() => {
    baseConfig = {
      googleOAuthAccessToken: 'ya29.valid-token',
      googleOAuthRefreshToken: 'refresh-token-123',
      googleOAuthClientId: 'client-id',
      googleOAuthClientSecret: 'client-secret',
      spreadsheetId: 'test-spreadsheet-id',
      range: 'Sheet1!A:B',
    }
    const fake = fakeFetch((req) => {
      if (req.url.includes('/token')) {
        return jsonResponse({ access_token: 'ya29.refreshed-token', expires_in: 3600 })
      }
      if (req.url.includes('/values/') && req.url.includes(':append')) {
        return jsonResponse({
          spreadsheetId: 'test-spreadsheet-id',
          tableRange: 'Sheet1!A1:B1',
          updates: {
            spreadsheetId: 'test-spreadsheet-id',
            updatedRange: 'Sheet1!A2:B2',
            updatedRows: 1,
            updatedColumns: 2,
            updatedCells: 2,
          },
        })
      }
      return jsonResponse({ error: 'not found' }, 404)
    })
    fetchMock = fake.fetch
    calls = fake.calls
  })

  it('maps dealstage and dealstageid to values array', async () => {
    const payload: HubSpotDealUpdatedPayload = {
      ...SOURCE_EXAMPLE,
      dealstage: 'qualifiedtobuy',
      dealstageid: '456',
    } as HubSpotDealUpdatedPayload

    const result = await handle(payload, { ...baseConfig, fetch: fetchMock })

    expect(calls.length).toBe(1)
    const sheetsCall = calls[0]
    expect(sheetsCall.method).toBe('POST')
    expect(sheetsCall.url).toContain('/values/Sheet1%21A%3AB:append')
    expect(sheetsCall.json).toEqual({
      majorDimension: 'ROWS',
      range: 'Sheet1!A:B',
      values: [['qualifiedtobuy', '456']],
    })
    expect(result.updatedRange).toBe('Sheet1!A2:B2')
  })

  it('uses only dealstage when dealstageid is missing', async () => {
    const payload: HubSpotDealUpdatedPayload = {
      ...SOURCE_EXAMPLE,
      dealstage: 'closedwon',
    } as HubSpotDealUpdatedPayload
    delete (payload as Record<string, unknown>).dealstageid

    await handle(payload, { ...baseConfig, fetch: fetchMock })

    const sheetsCall = calls[0]
    expect(sheetsCall.json).toEqual({
      majorDimension: 'ROWS',
      range: 'Sheet1!A:B',
      values: [['closedwon', '']],
    })
  })

  it('sends Bearer authorization header', async () => {
    const payload: HubSpotDealUpdatedPayload = {
      ...SOURCE_EXAMPLE,
      dealstage: 'appointmentscheduled',
    } as HubSpotDealUpdatedPayload

    await handle(payload, { ...baseConfig, fetch: fetchMock })

    const sheetsCall = calls[0]
    const authHeader = sheetsCall.headers.get('authorization')
    expect(authHeader).toBe('Bearer ya29.valid-token')
  })

  it('throws on missing dealstage', async () => {
    const payload = { ...SOURCE_EXAMPLE } as HubSpotDealUpdatedPayload
    delete (payload as Record<string, unknown>).dealstage

    await expect(handle(payload, { ...baseConfig, fetch: fetchMock })).rejects.toThrow(
      'Missing required field: dealstage',
    )
  })

  it('throws on missing deal ID', async () => {
    const payload = { ...SOURCE_EXAMPLE } as HubSpotDealUpdatedPayload
    delete (payload as Record<string, unknown>).hs_object_id
    delete (payload as Record<string, unknown>).objectId

    await expect(handle(payload, { ...baseConfig, fetch: fetchMock })).rejects.toThrow(
      'Missing required field: deal ID',
    )
  })

  it('refreshes token on 401 and retries', async () => {
    const fake = fakeFetch((req) => {
      if (req.url.includes('/token')) {
        return jsonResponse({ access_token: 'ya29.new-token', expires_in: 3600 })
      }
      if (req.url.includes('/values/') && req.url.includes(':append')) {
        const auth = req.headers.get('authorization')
        if (auth === 'Bearer ya29.expired-token') {
          return jsonResponse({ error: 'unauthorized' }, 401)
        }
        if (auth === 'Bearer ya29.new-token') {
          return jsonResponse({
            spreadsheetId: 'test-spreadsheet-id',
            tableRange: 'Sheet1!A1:B1',
            updates: {
              spreadsheetId: 'test-spreadsheet-id',
              updatedRange: 'Sheet1!A3:B3',
              updatedRows: 1,
              updatedColumns: 2,
              updatedCells: 2,
            },
          })
        }
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: HubSpotDealUpdatedPayload = {
      ...SOURCE_EXAMPLE,
      dealstage: 'appointmentscheduled',
    } as HubSpotDealUpdatedPayload

    const result = await handle(payload, {
      ...baseConfig,
      googleOAuthAccessToken: 'ya29.expired-token',
      fetch: fake.fetch,
    })

    expect(fake.calls.length).toBe(2)
    expect(fake.calls[0].url).toContain('/token')
    expect(fake.calls[1].headers.get('authorization')).toBe('Bearer ya29.new-token')
    expect(result.updatedRange).toBe('Sheet1!A3:B3')
  })

  it('throws on non-2xx response from Google Sheets', async () => {
    const fake = fakeFetch((req) => {
      if (req.url.includes('/values/') && req.url.includes(':append')) {
        return jsonResponse({ error: 'quota exceeded' }, 429)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: HubSpotDealUpdatedPayload = {
      ...SOURCE_EXAMPLE,
      dealstage: 'appointmentscheduled',
    } as HubSpotDealUpdatedPayload

    await expect(handle(payload, { ...baseConfig, fetch: fake.fetch })).rejects.toThrow(
      'Google Sheets append failed: 429 Too Many Requests',
    )
  })

  it('throws on token refresh failure', async () => {
    const fake = fakeFetch((req) => {
      if (req.url.includes('/token')) {
        return jsonResponse({ error: 'invalid_grant' }, 400)
      }
      if (req.url.includes('/values/') && req.url.includes(':append')) {
        return jsonResponse({ error: 'unauthorized' }, 401)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: HubSpotDealUpdatedPayload = {
      ...SOURCE_EXAMPLE,
      dealstage: 'appointmentscheduled',
    } as HubSpotDealUpdatedPayload

    await expect(handle(payload, { ...baseConfig, fetch: fake.fetch })).rejects.toThrow(
      'Failed to refresh Google OAuth token: 400 Bad Request',
    )
  })
})

